#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""零使用 asmdef 边报告/基线门禁（只减不增）。

统计口径（代码区/顶层类型**复用 domain-matrix.py 的实现**，不另造第二套定义）：
- 边候选 = arch/units.json 中源 unit 的 references 指向**另一 unit** 的条目；
  外部程序集（externalAssemblies）不在 unit→unit 范围。
- 源代码区 = 源 unit path 下、**归属该 unit** 的 .cs（按最长路径匹配；嵌套子单元
  的文件归子单元，不重复计入父单元）；排除测试与生成物（Tests/Test/Generated 目录、
  *.g.cs、// <auto-generated> 头、.dotnet/obj/bin 等构建目录）。
- 只统计代码区（去 //、///、/* */ 注释与字符串字面量）；只统计 namespace 块内
  depth=1 的顶层类型声明（class/struct/interface/enum/delegate，嵌套类型不单列）；
  计数单位 = 出现次数。
- 目标 unit 的任一顶层类型名在源 unit 代码区出现 0 次 => 源→目标为零使用边。
  同名类型被多个 unit 声明时，出现该名即对每个声明 unit 各计一次（过近似，减少假零）。
- --write 生成/重写基线；--check 要求**当前零使用集合是基线的子集**（只减不增），
  当前出现基线外的新边即失败；基线中已消失的边允许（run --write 收紧）。

基线：arch/zero-use-edges.json（版本/生成时间/边列表/口径说明）。
调试/测试可用 --model / --baseline 指向替代模型与基线。
"""
from __future__ import annotations

import argparse
import importlib.util
import json
import re
import sys
from collections import Counter
from datetime import datetime
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from _common import EXIT_FAIL, EXIT_OK, configure_stdio, fail, info, repo_root, warn  # noqa: E402

ROOT = repo_root()
MODEL_REL = Path("arch") / "units.json"
BASELINE_REL = Path("arch") / "zero-use-edges.json"

# 构建/缓存目录：不属于源代码区。
IGNORED_DIR_PARTS = {
    ".dotnet", "obj", "bin", "Library", "Temp", "Logs", "UserSettings",
    ".vs", ".git", "__pycache__", "node_modules",
}
# 测试与生成物：按目录段与文件名约定排除（口径见模块 docstring）。
TEST_DIR_PARTS = {"Tests", "Test"}
GENERATED_DIR_PARTS = {"Generated"}


def load_surface_rules():
    """加载 domain-matrix.py 的代码区/顶层类型口径（唯一实现，不复制）。"""
    path = Path(__file__).resolve().parent / "domain-matrix.py"
    spec = importlib.util.spec_from_file_location("_domain_matrix_surface", path)
    if spec is None or spec.loader is None:
        raise SystemExit("zero-use-edges: 无法加载 domain-matrix.py 的统计口径")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


SURFACE = load_surface_rules()


def load_units(model_path: Path) -> list:
    if not model_path.is_file():
        raise SystemExit("zero-use-edges: 缺模型 " + str(model_path))
    data = json.loads(model_path.read_text(encoding="utf-8-sig"))
    units = []
    seen = set()
    for item in data.get("units") or []:
        unit_id = item.get("id")
        path = item.get("path")
        if not unit_id or not path:
            raise SystemExit("zero-use-edges: 模型 unit 缺 id/path")
        if unit_id in seen:
            raise SystemExit("zero-use-edges: 模型 unit id 重复：" + unit_id)
        seen.add(unit_id)
        units.append({
            "id": unit_id,
            "path": str(path).rstrip("/"),
            "references": list(item.get("references") or []),
        })
    if not units:
        raise SystemExit("zero-use-edges: 模型没有 unit")
    return units


def is_excluded(relative: str) -> bool:
    parts = relative.split("/")
    if any(part in IGNORED_DIR_PARTS for part in parts):
        return True
    if any(part in TEST_DIR_PARTS for part in parts):
        return True
    if any(part in GENERATED_DIR_PARTS for part in parts):
        return True
    return relative.endswith(".g.cs")


def is_generated_header(text: str) -> bool:
    return any("<auto-generated>" in line for line in text.splitlines()[:5])


def collect_sources(units: list) -> dict:
    """按最长路径归属收集每个 unit 的 .cs（排除测试/生成物）。"""
    ordered = sorted(units, key=lambda unit: len(unit["path"]), reverse=True)
    for unit in units:
        if not (ROOT / unit["path"]).is_dir():
            raise SystemExit(
                "zero-use-edges: unit " + unit["id"] + " 路径不存在：" + unit["path"]
            )
    files = {unit["id"]: [] for unit in units}
    for unit in units:
        base = ROOT / unit["path"]
        for path in sorted(base.rglob("*.cs")):
            relative = path.relative_to(ROOT).as_posix()
            if is_excluded(relative):
                continue
            owner = next(
                (candidate["id"] for candidate in ordered
                 if relative.startswith(candidate["path"] + "/")),
                None,
            )
            if owner == unit["id"]:
                files[unit["id"]].append(relative)
    return files


def scan_unit(files: list) -> tuple:
    """返回 (顶层类型名集合, 标识符出现次数)；与 domain-matrix 的 \\bNAME\\b 计数等义。"""
    names = set()
    counts = Counter()
    for relative in files:
        text = SURFACE.read_text(ROOT / relative)
        if is_generated_header(text):
            continue
        code = SURFACE.strip_comments_and_strings(text)
        names |= SURFACE.top_level_types(code)
        counts.update(re.findall(r"\w+", code))
    return names, counts


def compute_zero_use_edges(units: list, files: dict) -> list:
    known = {unit["id"] for unit in units}
    types = {}
    counts = {}
    for unit in units:
        types[unit["id"]], counts[unit["id"]] = scan_unit(files[unit["id"]])
    edges = []
    for unit in units:
        source = unit["id"]
        for target in unit["references"]:
            if target == source or target not in known:
                continue  # 外部程序集不在 unit→unit 范围
            uses = sum(counts[source].get(name, 0) for name in types[target])
            if uses == 0:
                edges.append((source, target))
    return sorted(edges)


def load_baseline_edges(path: Path) -> set:
    if not path.is_file():
        raise SystemExit(
            "zero-use-edges: 缺基线 " + str(path) + "（先跑 --write 生成）"
        )
    data = json.loads(path.read_text(encoding="utf-8-sig"))
    if data.get("version") != 1:
        raise SystemExit("zero-use-edges: 基线 version 必须为 1：" + str(path))
    raw = data.get("edges")
    if not isinstance(raw, list):
        raise SystemExit("zero-use-edges: 基线缺 edges 数组：" + str(path))
    edges = set()
    for index, item in enumerate(raw):
        if not isinstance(item, dict) or not item.get("from") or not item.get("to"):
            raise SystemExit("zero-use-edges: 基线 edges[" + str(index) + "] 缺 from/to")
        edges.add((item["from"], item["to"]))
    return edges


def render_baseline(edges: list, model_rel: str) -> str:
    payload = {
        "version": 1,
        "generatedAt": datetime.now().astimezone().isoformat(timespec="seconds"),
        "generator": "python scripts/gate/zero-use-edges.py --write",
        "model": model_rel,
        "glossary": {
            "edge": "源 unit 的 asmdef references 指向另一 unit，且该源 unit 代码区出现目标 unit 顶层类型名的次数为 0。",
            "codeRegion": "源 unit path 下、归属该 unit 的 .cs（最长路径匹配；嵌套子单元的文件归子单元）；去 // /// /* */ 注释与字符串字面量。",
            "topLevelTypes": "namespace 块内 depth=1 的 class/struct/interface/enum/delegate；嵌套类型不单列；实现复用 scripts/gate/domain-matrix.py。",
            "countUnit": "出现次数（同一行多次出现分别计）；标识符 token 计数与 \\bNAME\\b 等义。",
            "sameNameTypes": "同名类型被多个 unit 声明时，出现该名即对每个声明 unit 各计一次（过近似，减少假零）。",
            "externalAssemblies": "references 中的外部程序集（arch/units.json externalAssemblies）不参与 unit→unit 边。",
            "emptyTarget": "目标 unit 未解析出顶层类型名时，其全部引用按零使用计（当前基线无此情况）。",
            "excluded": "测试（Tests/Test 目录段）与生成物（Generated 目录段、*.g.cs、// <auto-generated>）及 .dotnet/obj/bin 等构建目录不计。",
            "check": "--check 要求当前零使用集合是基线的子集（只减不增）；当前出现基线外的新边即失败，基线中已消失的边允许通过。",
        },
        "edges": [{"from": source, "to": target} for source, target in edges],
    }
    return json.dumps(payload, ensure_ascii=False, indent=2) + "\n"


def resolve(path_value: str) -> Path:
    path = Path(path_value)
    return path if path.is_absolute() else ROOT / path


def report_diff(current: set, baseline: set) -> int:
    new_edges = sorted(current - baseline)
    missing = sorted(baseline - current)
    if new_edges:
        fail("quality/zero-use-edges", "新增零使用边未登记（只减不增）：")
        for source, target in new_edges:
            print("[quality/zero-use-edges]   " + source + " -> " + target)
        print(
            "[quality/zero-use-edges]   如确属设计基线更新：python scripts/gate/zero-use-edges.py --write，并评审差异",
            file=sys.stderr,
        )
        return EXIT_FAIL
    if missing:
        info(
            "quality/zero-use-edges",
            "基线中 " + str(len(missing)) + " 条已消失（只减不增，可通过 --write 收紧）",
        )
    info(
        "quality/zero-use-edges",
        "OK: 当前 " + str(len(current)) + " 条零使用边（基线 " + str(len(baseline)) + " 条，只减不增）",
    )
    return EXIT_OK


def main() -> int:
    configure_stdio()
    parser = argparse.ArgumentParser(description="零使用 asmdef 边基线（--check 只减不增）")
    parser.add_argument("--write", action="store_true", help="重写基线（默认 --check）")
    parser.add_argument("--check", action="store_true", help="校验当前集合 ⊆ 基线（默认行为）")
    parser.add_argument("--baseline", default=str(BASELINE_REL), help="基线路径（默认 arch/zero-use-edges.json）")
    parser.add_argument("--model", default=str(MODEL_REL), help="架构模型路径（默认 arch/units.json）")
    args = parser.parse_args()

    model_path = resolve(args.model)
    baseline_path = resolve(args.baseline)
    units = load_units(model_path)
    files = collect_sources(units)
    edges = compute_zero_use_edges(units, files)

    if args.write:
        model_rel = model_path.relative_to(ROOT).as_posix() if model_path.is_relative_to(ROOT) else model_path.as_posix()
        content = render_baseline(edges, model_rel)
        previous = load_baseline_edges(baseline_path) if baseline_path.is_file() else set()
        baseline_path.parent.mkdir(parents=True, exist_ok=True)
        baseline_path.write_text(content, encoding="utf-8", newline="\n")
        added = sorted(set(edges) - previous)
        removed = sorted(previous - set(edges))
        if added:
            warn("quality/zero-use-edges", "相对旧基线新增 " + str(len(added)) + " 条：" +
                 ", ".join(source + "->" + target for source, target in added))
        if removed:
            info("quality/zero-use-edges", "相对旧基线消失 " + str(len(removed)) + " 条")
        info("quality/zero-use-edges", "wrote " + str(baseline_path) + "（" + str(len(edges)) + " 条）")
        return EXIT_OK

    baseline = load_baseline_edges(baseline_path)
    return report_diff(set(edges), baseline)


if __name__ == "__main__":
    sys.exit(main())
